"""Decode the ARM64X-specific metadata of a PE file.

Uses the Windows IMAGE_LOAD_CONFIG_DIRECTORY64 layout, which is what the
Windows loader actually reads. It agrees with LLVM's own
coff_load_configuration64 on the offsets that matter here (CHPEMetadataPointer
at 0xC8, DynamicValueRelocTableOffset at 0xE0), but the two disagree about
the fields around them: LLVM keeps a 64-bit DynamicValueRelocTable at 0xC0
and puts DynamicValueRelocTableSection at 0xE4, where Windows keeps
DynamicValueRelocTableSize, and Windows keeps the section index at 0xC4.

Also decodes the ARM64X dynamic relocation table that lives in the section
named by the load config's DynamicValueRelocTableSection, since that table is
what tells the loader how to build the EC (x64) view of the image.
"""
import struct
import sys

# IMAGE_LOAD_CONFIG_DIRECTORY64 field offsets.
LC_SIZE = 0x000
LC_SECURITY_COOKIE = 0x058
LC_SEHANDLER_TABLE = 0x060
LC_SEHANDLER_COUNT = 0x068
LC_GUARD_CF_CHECK = 0x070
LC_GUARD_CF_DISPATCH = 0x078
LC_GUARD_CF_TABLE = 0x080
LC_GUARD_CF_COUNT = 0x088
LC_GUARD_FLAGS = 0x090
LC_CODE_INTEGRITY = 0x094
LC_CI_CATALOG = 0x098
LC_CI_CATALOG_OFF = 0x09C
LC_CI_RESERVED = 0x0A0
LC_GUARD_IAT_TABLE = 0x0A4
LC_GUARD_IAT_COUNT = 0x0AC
LC_GUARD_LJ_TABLE = 0x0B4
LC_GUARD_LJ_COUNT = 0x0BC
LC_DYN_RELOC_SIZE = 0x0C4        # DWORD
LC_CHPE_METADATA_PTR = 0x0C8      # ULONGLONG
LC_GUARD_RF_VERIFY = 0x0D0
LC_GUARD_RF_DISPATCH = 0x0D8
LC_DYN_RELOC_OFFSET = 0x0E0       # DWORD
LC_DYN_RELOC_SECTION = 0x0E4      # WORD: 1-based index of the section
                                   # holding the ARM64X relocation table

# IMAGE_DVRT_ARM64X fixup types.
FIXUP = {0x0: "ZEROFILL", 0x1: "VALUE", 0x2: "DELTA"}


def analyze(path):
    d = open(path, "rb").read()
    pe = struct.unpack_from("<I", d, 0x3C)[0]
    coff = pe + 4
    machine, nsec = struct.unpack_from("<HH", d, coff)
    so = struct.unpack_from("<H", d, coff + 16)[0]
    opt = coff + 20
    dllchars = struct.unpack_from("<H", d, opt + 70)[0]
    ddoff = opt + 112
    ndd = struct.unpack_from("<I", d, ddoff - 4)[0]
    dirs = [struct.unpack_from("<II", d, ddoff + 8 * i) for i in range(ndd)]
    soff = opt + so
    secs = []
    for i in range(nsec):
        b = soff + 40 * i
        nm = d[b:b + 8].rstrip(b"\0").decode("ascii", "replace")
        vs, va, rs, ro = struct.unpack_from("<IIII", d, b + 8)
        secs.append((nm, va, vs, ro, rs))

    def off(rva):
        for nm, va, vs, ro, rs in secs:
            if va <= rva < va + max(vs, rs):
                return ro + (rva - va)
        return None

    def cstr(o):
        e = d.find(b"\0", o)
        return d[o:e].decode("ascii", "replace")

    print(f"===== {path}")
    print(f"  machine=0x{machine:04X} dllchars=0x{dllchars:04X} nsec={nsec}")
    for i, (nm, va, vs, ro, rs) in enumerate(secs):
        print(f"    sec[{i}] {nm:<10} va=0x{va:05X} vsize=0x{vs:05X} "
              f"raw=0x{ro:05X} rawsz=0x{rs:05X}")

    # Export directories.
    for i, (va, sz) in enumerate(dirs):
        if i != 0 or not va:
            continue
        o = off(va)
        fl, ts, maj, mn, nameRVA, baseOrd, nf, nn, fr, nr, orr = \
            struct.unpack_from("<IIHHIIIIIII", d, o)
        print(f"    export[datadir0] rva=0x{va:05X} dll={cstr(off(nameRVA))} "
              f"nfunc={nf} nname={nn}")

    lcva, lcsz = dirs[10] if len(dirs) > 10 else (0, 0)
    if not lcva:
        print("  no load config")
        return
    o = off(lcva)
    size = struct.unpack_from("<I", d, o + LC_SIZE)[0]
    print(f"  load config @0x{lcva:05X} size=0x{size:X}")

    def u32(x):
        return struct.unpack_from("<I", d, o + x)[0]

    def u64(x):
        return struct.unpack_from("<Q", d, o + x)[0]

    for name, off_ in [("SecurityCookie", LC_SECURITY_COOKIE),
                       ("SEHandlerTable", LC_SEHANDLER_TABLE),
                       ("SEHandlerCount", LC_SEHANDLER_COUNT),
                       ("GuardCFCheck", LC_GUARD_CF_CHECK),
                       ("GuardCFDispatch", LC_GUARD_CF_DISPATCH),
                       ("GuardCFFunctionTable", LC_GUARD_CF_TABLE),
                       ("GuardCFFunctionCount", LC_GUARD_CF_COUNT),
                       ("GuardFlags", LC_GUARD_FLAGS),
                       ("CodeIntegrity", LC_CODE_INTEGRITY),
                       ("CodeIntegrityCatalog", LC_CI_CATALOG),
                       ("GuardAddressTakenIatEntryTable", LC_GUARD_IAT_TABLE),
                       ("GuardLongJumpTargetTable", LC_GUARD_LJ_TABLE),
                       ("GuardRFVerifyStackPointerFnPtr", LC_GUARD_RF_VERIFY)]:
        v = u32(off_)
        if v:
            print(f"    {name:<36} = 0x{v:08X}")

    dynsec = struct.unpack_from("<H", d, o + LC_DYN_RELOC_SECTION)[0]
    dynoff = u32(LC_DYN_RELOC_OFFSET)
    dynsize = u32(LC_DYN_RELOC_SIZE)
    chpe = u64(LC_CHPE_METADATA_PTR)
    print(f"    {'CHPEMetadataPointer':<36} = 0x{chpe:016X}")
    print(f"    {'DynamicValueRelocTableSection':<36} = {dynsec}")
    print(f"    {'DynamicValueRelocTableOffset':<36} = 0x{dynoff:X}")
    print(f"    {'DynamicValueRelocTableSize':<36} = 0x{dynsize:X}")
    if dynsec:
        print(f"    {'-> relocation table section':<36} = "
              f"{secs[dynsec - 1][0] if dynsec <= len(secs) else '?'}")

    if chpe:
        co = off(chpe & 0x7FFFFFFF)
        if co is not None:
            print(f"  CHPE metadata @0x{chpe & 0x7FFFFFFF:05X}:")
            names = ["Version", "CodeMap", "CodeMapCount",
                     "CodeRangesToEntryPoints", "RedirectionMetadata",
                     "DispatchCallNoRedirect", "DispatchRet", "DispatchCall",
                     "DispatchICall", "DispatchICallCFG", "AlternateEntryPoint",
                     "AuxiliaryIAT", "CodeRangesToEntryPointsCount",
                     "RedirectionMetadataCount", "GetX64Information",
                     "SetX64Information", "ExtraRFETable", "ExtraRFETableSize",
                     "DispatchFptr", "AuxiliaryIATCopy",
                     "AuxiliaryDelayloadIAT", "AuxiliaryDelayloadIATCopy",
                     "HybridImageInfoBitfield"]
            for k, nm in enumerate(names):
                v = struct.unpack_from("<I", d, co + 4 * k)[0]
                if v:
                    print(f"      {nm:<32} = 0x{v:08X}")

    # ARM64X dynamic relocation table.
    if dynsec and dynsec <= len(secs):
        nm, va, vs, ro, rs = secs[dynsec - 1]
        base = ro + dynoff
        if base + 8 <= len(d):
            ver, tsize = struct.unpack_from("<II", d, base)
            print(f"  dyn reloc table in section {dynsec} ({nm}) "
                  f"@0x{base:X}: version={ver} size=0x{tsize:X}")
            if ver == 1:
                # {Version, Size} header, then a relocation record
                # {Symbol, BaseRelocSize, padding} whose payload is a flat
                # stream of ARM64X fixups.
                #
                # Each fixup starts with a word holding the target offset in
                # its low 12 bits, the fixup type in bits 12-13 and two
                # type-specific flag bits in bits 14-15. ZEROFILL writes no
                # payload, VALUE writes a 2, 4 or 8 byte payload whose length
                # is encoded in the flag bits, and DELTA writes a second word
                # holding a signed delta.
                p = base + 8
                sym, brs = struct.unpack_from("<QI", d, p)
                print(f"      symbol=0x{sym:X} baseRelocSize=0x{brs:X}")
                p += 16
                end = min(p + brs, len(d))
                while p + 2 <= end:
                    hdr = struct.unpack_from("<H", d, p)[0]
                    ftype = (hdr >> 12) & 0x3
                    offset = hdr & 0xFFF
                    flags = (hdr >> 14) & 0x3
                    p += 2
                    if ftype == 0:            # ZEROFILL
                        size = 1 << flags
                        val = None
                    elif ftype == 1:          # VALUE
                        size = 2 << flags
                        val = int.from_bytes(d[p:p + size], "little")
                        p += size
                    else:                    # DELTA
                        raw = struct.unpack_from("<H", d, p)[0]
                        p += 2
                        if raw & (1 << 15):
                            raw >>= 3
                        else:
                            raw >>= 2
                        val = -raw if hdr & (1 << 14) else raw
                        size = 4
                    if ftype == 0:
                        print(f"      fixup: ZEROFILL offset=0x{offset:X}")
                    elif ftype == 1:
                        print(f"      fixup: VALUE offset=0x{offset:X} "
                              f"size={size} value=0x{val:X}")
                    else:
                        print(f"      fixup: DELTA offset=0x{offset:X} "
                              f"delta={val}")
            elif ver == 2 and p + 24 <= len(d):
                # Version 2: header + ARM64X fixups.
                hdrsz, fixsz, sym, symgrp, flags = struct.unpack_from(
                    "<IIQII", d, p)
                print(f"      v2 header: hdrSize={hdrsz} fixupInfoSize={fixsz} "
                      f"symbol=0x{sym:X} group=0x{symgrp:X} flags={flags}")
                q = p + hdrsz
                while q + 4 <= min(p + hdrsz + fixsz, len(d)):
                    hdr = struct.unpack_from("<I", d, q)[0]
                    ftype = hdr & 0x3
                    size = (hdr >> 2) & 0x3
                    rva = hdr >> 4
                    size = 8 if size == 3 else 1 << size
                    val = 0
                    if ftype == 1 and q + 4 + size <= len(d):
                        val = int.from_bytes(d[q + 4:q + 4 + size], "little")
                    print(f"      v2 fixup: type={FIXUP.get(ftype, ftype)} "
                          f"size={size} rva=0x{rva:X} value=0x{val:X}")
                    q += 4 + size

    for nm, va, vs, ro, rs in secs:
        if nm == ".a64xrm":
            body = d[ro:ro + vs]
            print(f"  .a64xrm vsize=0x{vs:X}: {body.hex()}")
        if nm == ".hexpthk":
            print(f"  .hexpthk vsize=0x{vs:X}")


for p in sys.argv[1:]:
    analyze(p)
    print()
